#include <iostream>
using namespace std;

long long fact(int n) {
    if (n == 0) {
        return 1;
    }
    return n * fact(n - 1);
}

int main() {
    int n = 0;
    cin >> n;

    cout << "{hello}" << endl;
    cout << n << " 的阶乘是 " << fact(n) << endl;
    return 0;
}
